  homeQuiet: 'https://refy.design/demo/ape-silencioso.webp',
  homeStudio: 'https://refy.design/demo/ape-studio.webp',
  homeBalcony: 'https://refy.design/demo/ape-varanda.webp',
};
const homes = [
  {
    src: photos.homeBalcony,
    alt: 'Building facade with plants on every balcony',
    caption: 'Building',
  },
  {
    src: photos.homeQuiet,
    alt: 'Living room with large windows facing the trees',
    caption: 'Living room',
  },
  {
    src: photos.homeStudio,
    alt: 'Living room with a gray sofa and a large plant',
    caption: 'Lounge',
  },
  {
    src: photos.homePenthouse,
    alt: 'Balcony overlooking the sea and a coastal town',
    caption: 'Balcony',
  },
  {
    src: photos.coverSunday,
    alt: 'Open window next to plants',
    caption: 'Bedroom window',
  },
  {
    src: photos.coverPlateau,
    alt: 'Green field near the building',
    caption: 'Park nearby',
  },
];
export function Example() {
  const args: Pick<ComponentProps<typeof ImageGallery>, 'images' | 'label'> = {
    images: homes,
    label: 'Apartment photos',
  };
  return <ImageGallery {...args} />;
}

